void mainImage(out vec4 fragColor, in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;
 vec3 src=texture(iChannel0,uv).rgb;
 float l=dot(src,vec3(0.2126,0.7152,0.0722));
 float grain=fract(sin(dot(floor(fragCoord)+floor(iTime*24.0),vec2(12.9898,78.233)))*43758.5453)-0.5;
 float v=1.0-smoothstep(0.3,0.75,length(uv-0.5));
 float scan=0.9+0.1*sin(fragCoord.y*1.6);
 l=clamp(l*U.p0.x+grain*U.p0.y,0.0,1.0);
 fragColor=vec4(vec3(0.09,1.0,0.25)*l*v*scan,1.0);
}
